mapper.sql:
with tmpTable as ( select T1.FINPROD_ID, T1.AMOUNT * NVL(T1.FACE_VALUE, 1) QTY, T1.CASH_TYPE, T1.CASH_ID, T1.MDATE, T1.CDATE, double(T1.CASH_AMT / T1.CASH_BASEAMT) * T1.AMOUNT * NVL(T1.FACE_VALUE, 1) fpriceAmt,/*理论本息总额*/ case T1.CASH_TYPE when '${CASH_CLASS_TYPE01}' then 0 else double(T1.PRIN_AMT / T1.CASH_BASEAMT) * T1.AMOUNT * NVL(T1.FACE_VALUE, 1) end prinAmt,/*还本金额*/ T1.PORTFOLIO_ID, T1.SEC_ACCT_ID, double(T1.INT_AMT / T1.CASH_BASEAMT) * T1.AMOUNT * NVL(T1.FACE_VALUE, 1) intAmt,/*理论利息*/ T1.PAY_DATE FROM ( select * from ( SELECT T1.AMOUNT, t1.finprod_id, t1.sec_acct_id, t1.cdate, t6.cash_type, T6.CASH_ID, T6.MDATE, T6.CASH_AMT,T1.PORTFOLIO_ID, T6.CASH_BASEAMT, T1.FACE_VALUE, T6.PRIN_AMT, T6.INT_AMT, T6.PAY_DATE, rank() over(partition by t6.finprod_id order by t6.mdate) rank from PTL_SEC_POSITION T1 INNER JOIN FIN_CASH_PLAN T6 on t1.cdate < t6.mdate and t1.finprod_id=t6.finprod_id INNER JOIN PTL_PORTFOLIO pp on T1.PORTFOLIO_ID = pp.PORTFOLIO_ID and NOT EXISTS (SELECT 1 FROM TRD_FIN_PRODUCT_DEAL_TOTAL tfpdt where tfpdt.TRADE_STATUS = #{TRADE_STATUS01} and tfpdt.IS_CANCEL = #{YESNO_N} AND (tfpdt.CHL_ID = T1.SEC_ACCT_ID OR (T1.SEC_ACCT_ID = '999999' and tfpdt.CHL_ID is null)) AND T1.PORTFOLIO_ID =tfpdt.PORTFOLIO_ID AND t1.finprod_id=tfpdt.FINPROD_ID and T6.MDATE = tfpdt.MDATE ) AND NOT EXISTS (SELECT 1 FROM WFL_TRD_FIN_PRODUCT_DEAL_TOTAL tfpdt where tfpdt.WORKFLOW_STATUS = #{STATUS_A} AND T1.FINPROD_ID=TFPDT.FINPROD_ID AND (tfpdt.CHL_ID = T1.SEC_ACCT_ID OR (T1.SEC_ACCT_ID = '999999' and tfpdt.CHL_ID is null)) AND T1.PORTFOLIO_ID =tfpdt.PORTFOLIO_ID and T6.MDATE >= tfpdt.MDATE )
AND NOT EXISTS ( SELECT 1 FROM PTL_SEC_POSITION tpsp where tpsp.HODING_TYPE = #{POSITION_TYPE03} and tpsp.PORTFOLIO_ID = T1.PORTFOLIO_ID and tpsp.SEC_ACCT_ID = T1.SEC_ACCT_ID and tpsp.FINPROD_ID = T1.FINPROD_ID and tpsp.CDATE > T1.CDATE and tpsp.CDATE < T6.MDATE ) and nvl(pp.PARENT_PORTFOLIO_ID,'null') = 'null' and T6.PAY_DATE >= #{PLATEFORM_DATE}
and T1.FINPROD_ID = #{finprodId}
AND T1.HODING_TYPE = #{POSITION_TYPE03} AND T6.FINPROD_TYPE2 = #{FINPROD_TYPE_TGF07} and T1.AMOUNT > 0 where T1.PORTFOLIO_ID
AND T1.PORTFOLIO_ID IN
#{item}
) where rank = 1 ) T1 )

choose.when:
SELECT #{statusValid} statusValid, T1.TOTLE_TRADE_ID busiCode, T1.CCY, T3.PA_BUSS_TYPE, T1.PS cashType,
T1.CHL_ID chlId, TC4.FINPROD_NAME channelName,
FPD.COLLECT_TYPE collectType, T1.FEE_AMT - nvl(T5.FEE_AMT, 0) channelFee, NVL(T1.FPRICE_AMT,T1.TRADE_AMT) tradeAmtReal, CASE WHEN T1.CHL_ID IS NULL THEN 0 ELSE 1 END channel,
fprod_type.TYPE_6 assetType, T1.FINPROD_ID, T4.FINPROD_MARKET_ID, T4.FINPROD_NAME finprodMarketName, T1.VDATE vdateProd/*计息开始日*/, T1.MDATE mdateProd/*计息结束日*/, fccr.BASIS, T4.VDATE, T4.MDATE, T4.ENTRUSTER, T3.RATE*100 earlyWithdrawalRate,
fccr.YIELD*100 yield,
T5.FEE_AMT,
T3.THEORY_INT, T3.THEORY_AMT fpriceAmt/*理论本息总额*/,
T3.REMAIN_PRIN_AMT remainPrinAmt,
T3.THEORY_PRIN earlyWithdrawalAmt, T1.INT_AMT, T1.TRADE_AMT,/*实收本息总额*/ T1.TRADE_DATE tradeDate/*资金到账日*/, fccrt_2.YIELD*100 loadRate FROM TRD_FIN_PRODUCT_DEAL_TOTAL T1 LEFT JOIN PTL_PORTFOLIO T2 ON T2.PORTFOLIO_ID = T1.PORTFOLIO_ID LEFT JOIN PA_TRD_FIN_PRODUCT_DEAL_TOTAL T3 ON T1.TOTLE_TRADE_ID = T3.TOTLE_TRADE_ID LEFT JOIN FIN_PRODUCT T4 ON T1.FINPROD_ID = T4.FINPROD_ID LEFT JOIN TRD_TRADE_FEE_DETAIL T5 on T5.TRADE_ID = T1.TOTLE_TRADE_ID
LEFT JOIN FIN_PRODUCT TC4 ON T1.CHL_ID = TC4.FINPROD_ID
LEFT JOIN FIN_PRODUCT_ADD FPD ON TC4.FINPROD_ID=FPD.FINPROD_ID
LEFT JOIN FIN_PRODUCT_TYPE fprod_type on fprod_type.FINPROD_ID = T1.FINPROD_ID
LEFT JOIN FIN_CASH_INFO fcinfo on fcinfo.FINPROD_ID = T1.FINPROD_ID and fcinfo.CASH_TYPE_2 = #{CASH_TYPE_2_C08}
LEFT JOIN FIN_CASH_CALC_RULE fccr on fccr.CASH_ID = fcinfo.CASH_ID and fccr.EFF_DATE <= T1.MDATE and not EXISTS ( select 1 from FIN_CASH_CALC_RULE fccr2 where fccr2.CASH_ID =fccr.CASH_ID and fccr2.EFF_DATE > fccr.EFF_DATE and fccr2.EFF_DATE <= T1.MDATE )
LEFT JOIN FIN_CASH_INFO fcinfo2 on fcinfo2.FINPROD_ID = T1.FINPROD_ID and fcinfo2.CASH_TYPE_2 = #{CASH_TYPE_2_C02}
LEFT JOIN FIN_CASH_CALC_RULE fccrt_2 on fccrt_2.CASH_ID = fcinfo2.CASH_ID and fccrt_2.EFF_DATE <= T1.MDATE and not EXISTS ( select 1 from FIN_CASH_CALC_RULE fccr_2 where fccr_2.CASH_ID =fccrt_2.CASH_ID and fccr_2.EFF_DATE > fccrt_2.EFF_DATE and fccr_2.EFF_DATE <= T1.MDATE ) WHERE T1.FINPROD_TYPE2 = #{FINPROD_TYPE_TGF07}
and T1.TRADE_STATUS = #{TRADE_STATUS01}
and T1.TOTLE_TRADE_ID = #{busiCode}
and T1.TRADE_STATUS = #{TRADE_STATUS01} and T1.IS_CANCEL = #{YESNO_Y} and T1.TOTLE_TRADE_ID = #{pTradeId}

select.if:
/*检索项目*/                SELECT
    listagg(t5.cash_id, ',')  within group ( order by t5.cash_id) cash_id,
    listagg(t5.CASH_TYPE, ',')  within group ( order by t5.cash_id) CASH_TYPE,
/*组合持仓.组合代码*/           T1.PORTFOLIO_ID,
    '${vDate}' vDate,
    '${mDate}' mDate,
    '${loadRate}' loadRate,

    pp.INVEST_YESORNO investYesorno,

/*组合持仓.数量*/               T1.AMOUNT,
/*现金流支付规则.支付频率 付息周期*/ T4.PAY_CYCLE CALC_RULE
/*检索对象 组合持仓*/         FROM PTL_SEC_POSITION T1
/*left join 标的类金融产品*/ LEFT JOIN FIN_PRODUCT T2
/*on 组合持仓.金融产品代码 = 标的类金融产品.金融产品代码*/ ON T1.FINPROD_ID = T2.FINPROD_ID
/*left join 现金流信息*/     LEFT JOIN FIN_CASH_INFO T3
/*on 标的类金融产品.金融产品代码 = 现金流信息.业务代码*/ ON T1.FINPROD_ID = T3.FINPROD_ID
/*and 现金流信息.现金流一级类型 = 数据字典缓存.现金流一级类型.利息*/ AND T3.CASH_TYPE_1 = #{CASH_TYPE_1_02}
/*and 现金流信息.现金流二级类型 = 数据字典缓存.现金流二级类型.利息*/ AND T3.CASH_TYPE_2 = #{CASH_TYPE_2_C02}
/*left join 现金流支付规则*/ LEFT JOIN FIN_CASH_PAY_RULE T4
/*on 现金流信息.现金流代码 = 现金流支付规则.现金流代码*/ ON T3.CASH_ID = T4.CASH_ID
/*and 生效日期 小于等于 传参.支付日 取最大生效日期的数据*/  AND T4.EFF_DATE <= to_date(#{adjustDate}, 'yyyy-MM-dd')
LEFT JOIN FIN_CASH_PLAN T5 ON T1.FINPROD_ID = T5.FINPROD_ID AND T5.MDATE = TO_DATE(#{adjustDate}, 'yyyy-MM-dd')
LEFT JOIN PTL_PORTFOLIO pp on pp.PORTFOLIO_ID = T1.PORTFOLIO_ID
/*检索条件              金融产品代码 = 传参.金融产品代码*/
where
nvl(pp.PARENT_PORTFOLIO_ID,'null') = 'null'
and T1.FINPROD_ID = #{finprodId}
/*and 持仓类型 = 数据字典缓存.持仓类型.实际*/  AND T1.HODING_TYPE = #{POSITION_TYPE03}
/*and 日期 = 传参.平台日*/ AND T1.CDATE < TO_DATE(#{adjustDate}, 'yyyy-MM-dd')


    AND T1.SEC_ACCT_ID = #{chlId}

AND T1.AMOUNT > 0


    AND NOT EXISTS (
    SELECT 1 FROM PTL_SEC_POSITION tpsp
    where tpsp.HODING_TYPE = #{POSITION_TYPE03}
    and tpsp.PORTFOLIO_ID = T1.PORTFOLIO_ID
    and tpsp.SEC_ACCT_ID = T1.SEC_ACCT_ID
    and tpsp.FINPROD_ID = T1.FINPROD_ID
    and tpsp.CDATE > T1.CDATE
    and tpsp.CDATE < TO_DATE(#{adjustDate}, 'YYYY-MM-DD')
    )
    /*不存在生效的交易*/
    and NOT EXISTS (SELECT 1 FROM TRD_FIN_PRODUCT_DEAL_TOTAL TPDA where TPDA.TRADE_STATUS = #{TRADE_STATUS01}
    AND TPDA.IS_CANCEL = #{YESNO_N} and TO_DATE(#{mDate}, 'YYYY-MM-DD') = TPDA.MDATE
    AND TPDA.FINPROD_ID = T1.FINPROD_ID
    AND T1.PORTFOLIO_ID =TPDA.PORTFOLIO_ID
    AND ((TPDA.CHL_ID is NULL and t1.sec_acct_id='999999') OR TPDA.CHL_ID = T1.SEC_ACCT_ID))

    /*不存在流程中的当期或之前的交易*/
    AND NOT EXISTS (SELECT 1 FROM WFL_TRD_FIN_PRODUCT_DEAL_TOTAL TPDA where TPDA.TRADE_STATUS = #{TRADE_STATUS01}
    AND TPDA.IS_CANCEL = #{YESNO_N} and TO_DATE(#{mDate}, 'YYYY-MM-DD') >= TPDA.MDATE
    AND TPDA.FINPROD_ID = T1.FINPROD_ID
    AND T1.PORTFOLIO_ID =TPDA.PORTFOLIO_ID
    AND ((TPDA.CHL_ID is NULL and t1.sec_acct_id='999999') OR TPDA.CHL_ID = T1.SEC_ACCT_ID))

AND T1.PORTFOLIO_ID 
group by T1.PORTFOLIO_ID,
         T1.AMOUNT,
         T4.PAY_CYCLE,
          pp.INVEST_YESORNO
    order by AMOUNT

/*检索项目*/
SELECT
/*组合交易.组合代码 组合*/
pp.PORTFOLIO_ID,
pp.PORTFOLIO_NAME,
/*现金流支付规则.支付频率 付息周期*/
fcpr.PAY_CYCLE CALC_RULE,
/*金融产品交易汇总业务流程表.交易份额*/
ROUND(DECODE(TOTAL.SHARE_AMT, NULL, PSP.AMOUNT, 0, PSP.AMOUNT, TOTAL.SHARE_AMT), 2) remainPrinAmt,

ROUND(PA_TOTAL.THEORY_PRIN, 2) returnAmount,
/*金融产品交易1.起息日 计息开始日*/
to_char(TOTAL.VDATE, 'yyyy-MM-dd') vDate,
/*金融产品交易1.到期日 计息结束日*/
to_char(TOTAL.MDATE, 'yyyy-MM-dd') mDate,
/*金融产品交易扩展1.区间票面利率 借款利率*/
PA_TOTAL.RATE*100 loadRate,
/*sum（金融产品交易扩展1.还本金额/理论利息，金融产品交易扩展2.还本金额/理论利息） 理论本息总额*/
ROUND(PA_TOTAL.THEORY_INT, 2) theoryInt,

ROUND(TOTAL.FEE_AMT, 2) channelFee,

ROUND(TOTAL.INT_AMT, 2) intAmt

    FROM WFL_TRD_FIN_PRODUCT_DEAL_TOTAL TOTAL
    LEFT JOIN WFL_PA_TRD_FIN_DEAL_TOTAL PA_TOTAL ON TOTAL.TOTLE_TRADE_ID = PA_TOTAL.TOTLE_TRADE_ID


    FROM TRD_FIN_PRODUCT_DEAL_TOTAL TOTAL
    LEFT JOIN PA_TRD_FIN_PRODUCT_DEAL_TOTAL PA_TOTAL ON TOTAL.TOTLE_TRADE_ID = PA_TOTAL.TOTLE_TRADE_ID

LEFT JOIN PTL_SEC_POSITION PSP ON PSP.FINPROD_ID = TOTAL.FINPROD_ID AND PSP.PORTFOLIO_ID = TOTAL.PORTFOLIO_ID AND PSP.SEC_ACCT_ID = TOTAL.CHL_ID  AND PSP.CDATE = TOTAL.MDATE
LEFT JOIN PTL_PORTFOLIO pp on pp.PORTFOLIO_ID = TOTAL.PORTFOLIO_ID
LEFT JOIN FIN_CASH_INFO fci ON TOTAL.FINPROD_ID = fci.FINPROD_ID
AND fci.CASH_TYPE_1 = #{CASH_TYPE_1_02} AND fci.CASH_TYPE_2 = #{CASH_TYPE_2_C02}
LEFT JOIN FIN_CASH_PAY_RULE fcpr on fcpr.CASH_ID = fci.CASH_ID and fcpr.EFF_DATE <= TOTAL.MDATE and  not EXISTS (
    select 1 from FIN_CASH_PAY_RULE fcpr_2
    where fcpr_2.EFF_DATE > fcpr.EFF_DATE
    and fcpr.CASH_ID = fcpr_2.CASH_ID
    and fcpr_2.EFF_DATE <= TOTAL.MDATE
)
/*检索条件*/
WHERE
/*金融产品交易1.金融产品代码 = 传参.金融产品代码*/
TOTAL.P_TOTLE_TRADE_ID = #{busiCode}

and nvl(pp.PARENT_PORTFOLIO_ID,'null') = 'null'

and TOTAL.PORTFOLIO_ID
